#!/usr/bin/env node
// Reads the lab numbers the browser needs from the single Config source
// (packages/domain/edu_it_domain/config.py) so no business number is hardcoded in
// apps/web (hands-on-labs Req 13.4, 15.5, 15.6, 15.8).
//
// As a CLI it writes `src/generated/lab-config.ts` (gitignored, regenerated by
// `build`, `pretest` and `pretypecheck`). The parser is also imported by tests.
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

const WEB_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const CONFIG_PY = path.resolve(
  WEB_DIR,
  '..',
  '..',
  'packages',
  'domain',
  'edu_it_domain',
  'config.py',
);

/** Config constant -> client field. `list` constants are tuples of timedeltas. */
const KEYS = {
  LAB_GRADING_MIN_INTERVAL: ['gradingMinIntervalMs', 'one'],
  LAB_WARNING_THRESHOLD: ['warningThresholdMs', 'one'],
  LAB_RESULT_POLL_INTERVAL: ['resultPollIntervalMs', 'one'],
  LAB_PROVISION_READY_TARGET: ['provisionSlowMs', 'one'],
  LAB_RECONNECT_WINDOW: ['reconnectWindowMs', 'one'],
  LAB_RECONNECT_BACKOFF: ['reconnectBackoffMs', 'list'],
};

const UNIT_MS = {
  milliseconds: 1,
  seconds: 1000,
  minutes: 60_000,
  hours: 3_600_000,
  days: 86_400_000,
};

/** Milliseconds of every `timedelta(...)` call in `expression`, in order. */
function timedeltas(name, expression) {
  const out = [];
  for (const call of expression.matchAll(/timedelta\(([^)]*)\)/g)) {
    let total = 0;
    for (const arg of call[1].split(',')) {
      const trimmed = arg.trim();
      if (trimmed === '') continue;
      const m = /^(\w+)\s*=\s*([0-9]+(?:\.[0-9]+)?)$/.exec(trimmed);
      if (!m || !(m[1] in UNIT_MS)) {
        throw new Error(`lab-config: cannot read ${name}: unsupported argument "${trimmed}"`);
      }
      total += Number(m[2]) * UNIT_MS[m[1]];
    }
    out.push(total);
  }
  return out;
}

/**
 * Parse the lab client numbers (milliseconds) from the text of config.py.
 * @param {string} source
 */
export function parseLabClientConfig(source) {
  const result = {};
  for (const [name, [field, shape]] of Object.entries(KEYS)) {
    const start = new RegExp(`^${name}:[^=]*=`, 'm').exec(source);
    if (!start) throw new Error(`lab-config: ${name} not found in config.py`);
    const rest = source.slice(start.index + start[0].length);
    const end = rest.search(/\n\s*\n|\n[A-Za-z_#]/);
    const expression = end === -1 ? rest : rest.slice(0, end);
    const values = timedeltas(name, expression);
    if (values.length === 0 || values.some((v) => !(v > 0))) {
      throw new Error(`lab-config: ${name} must be made of positive timedeltas`);
    }
    result[field] = shape === 'list' ? values : values[0];
  }
  return result;
}

export function readLabClientConfig(configPath = CONFIG_PY) {
  return parseLabClientConfig(fs.readFileSync(configPath, 'utf8'));
}

function main() {
  const config = readLabClientConfig();
  const outPath = path.join(WEB_DIR, 'src', 'generated', 'lab-config.ts');
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  const body =
    '// AUTO-GENERATED by apps/web/scripts/lab-config.mjs from\n' +
    '// packages/domain/edu_it_domain/config.py. DO NOT EDIT BY HAND.\n' +
    "import type { LabClientConfig } from '../lab-state.js';\n\n" +
    `export const labClientConfig: LabClientConfig = ${JSON.stringify(config, null, 2)};\n`;
  fs.writeFileSync(outPath, body);
  process.stdout.write(`lab-config: wrote ${outPath}\n`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    main();
  } catch (err) {
    process.stderr.write(`${/** @type {Error} */ (err).message}\n`);
    process.exit(1);
  }
}
